let PSEX='m',pickSt=0;
function showPick(){
  if(pickSt||started)return;pickSt=1;
  const m=document.getElementById('menu'),pk=document.getElementById('pick');
  m.classList.add('out');pk.classList.add('show');
  setTimeout(()=>{if(pickSt===1){m.style.display='none';const b=document.getElementById('gM');if(b)b.focus({preventScroll:true})}},800)}
function choosePlayer(sex){
  if(pickSt!==1||started)return;pickSt=2;PSEX=sex;
  const pk=document.getElementById('pick'),sel=document.getElementById(sex==='f'?'gF':'gM'),oth=document.getElementById(sex==='f'?'gM':'gF');
  sel.classList.add('sel');oth.classList.add('dim');
  const lab=document.getElementById('pickMsg');
  const go=()=>{
    const fin=()=>{pk.classList.add('leave');startGame();setTimeout(()=>{pk.style.display='none'},1000)};
    const wait=()=>{if(worldReady){fin()}else{lab.textContent='Carregando a floresta...';lab.classList.add('on');setTimeout(wait,120)}};
    setTimeout(wait,520)};
  if(sex==='f'){sheet.addEventListener('load',go,{once:true});sheet.src=FEMSHEET}else go()}
document.getElementById('gM').addEventListener('click',()=>choosePlayer('m'));
document.getElementById('gF').addEventListener('click',()=>choosePlayer('f'));
addEventListener('keydown',e=>{
  if(pickSt!==1)return;const k=e.key;
  if(k==='ArrowLeft'||k==='a'||k==='A'){e.preventDefault();document.getElementById('gM').focus()}
  else if(k==='ArrowRight'||k==='d'||k==='D'){e.preventDefault();document.getElementById('gF').focus()}
  else if(k==='Enter'||k===' '){const f=document.activeElement;e.preventDefault();choosePlayer(f&&f.id==='gF'?'f':'m')}
  else if(k==='m'||k==='M')choosePlayer('m');else if(k==='f'||k==='F')choosePlayer('f')});
