const keys={up:0,down:0,left:0,right:0,jump:0,run:0};
const KMAP={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'jump',ShiftLeft:'run',ShiftRight:'run'};
let lastAxis='v';
const axisOf=k=>(k==='left'||k==='right')?'h':(k==='up'||k==='down')?'v':'x';
addEventListener('keydown',e=>{
  if(!started){if(e.code==='Enter'||e.code==='Space'){e.preventDefault();startGame()}return}
  if(e.ctrlKey||e.metaKey||e.altKey)return;
  const k=KMAP[e.code];if(!k)return;
  e.preventDefault();
  if(!keys[k]&&axisOf(k)!=='x')lastAxis=axisOf(k);
  keys[k]=1;
});
addEventListener('keyup',e=>{const k=KMAP[e.code];if(k){e.preventDefault();keys[k]=0}});
function releaseAll(){keys.up=keys.down=keys.left=keys.right=keys.jump=keys.run=0;document.querySelectorAll('.pb.on').forEach(b=>b.classList.remove('on'))}
addEventListener('blur',releaseAll);
document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll()});
document.querySelectorAll('[data-k]').forEach(b=>{
  const k=b.dataset.k;
  b.addEventListener('pointerdown',e=>{e.preventDefault();b.classList.add('on');keys[k]=1;if(axisOf(k)!=='x')lastAxis=axisOf(k);b.setPointerCapture(e.pointerId)});
  ['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>{keys[k]=0;b.classList.remove('on')}));
});
addEventListener('contextmenu',e=>e.preventDefault());

/* ---- aleatório determinístico ---- */
function rnd(x,y){let h=Math.imul(x|0,374761393)^Math.imul(y|0,668265263);h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}

/* ---- mundo: [1]=grama [2]=terra [3]=areia [4]=água [5]=lama ---- */
const GRASS=1,DIRT=2,SAND=3,WATER=4,MUD=5;var DA;
const G=8,N=512,WS=G*N,SEED=1337,RIM=104;
const FL=new Float32Array(N*N),FX=new Float32Array(N*N),FY=new Float32Array(N*N),DM=new Float32Array(N*N),DN=new Float32Array(N*N),SN=new Float32Array(N*N);
