  for(let j=0;j<N;j++)for(let i=0;i<N;i++){
    const o=j*N+i,x=i*G,y=j*G;
    let h=fbm(i/95,j/95,SEED+3)*.6+vn(i/30,j/30,SEED+4)*.08+(i*.55+j*.45)/N*.25;
    for(const d of dips){const r=Math.hypot(i-d[0],j-d[1])/d[2];if(r<1.7)h-=.075*Math.exp(-r*r*2.2)}
    HT[o]=h;DN[o]=fbm(x/110,y/110,SEED+14);SN[o]=fbm(x/130,y/130,SEED+15);
  }
  /* escoamento: priority-flood (preenche depressões → lagos) + D8 */
  const fill=new Float32Array(NN),down=new Int32Array(NN).fill(-1),seen=new Uint8Array(NN),order=new Int32Array(NN);
  const hk=new Float32Array(NN+8),hi=new Int32Array(NN+8);let hn=0,cnt=0;
  const push=(c,k)=>{let i=hn++;while(i>0){const p=(i-1)>>1;if(hk[p]<=k)break;hk[i]=hk[p];hi[i]=hi[p];i=p}hk[i]=k;hi[i]=c};
  const pop=()=>{const top=hi[0];hn--;if(hn>0){const k=hk[hn],v=hi[hn];let i=0;for(;;){let c=2*i+1;if(c>=hn)break;if(c+1<hn&&hk[c+1]<hk[c])c++;if(hk[c]>=k)break;hk[i]=hk[c];hi[i]=hi[c];i=c}hk[i]=k;hi[i]=v}return top};
  for(let j=0;j<N;j++)for(let i=0;i<N;i++)if(i===0||j===0||i===N-1||j===N-1){const o=j*N+i;seen[o]=1;fill[o]=HT[o];push(o,HT[o])}
  while(hn){
    const c=pop();order[cnt++]=c;const ci=c%N,cj=(c/N)|0;
    for(let dj=-1;dj<=1;dj++)for(let di=-1;di<=1;di++){
      const x=ci+di,y=cj+dj;if((!di&&!dj)||x<0||y<0||x>=N||y>=N)continue;
      const n=y*N+x;if(seen[n])continue;seen[n]=1;down[n]=c;fill[n]=Math.max(HT[n],fill[c]+1e-5);push(n,fill[n]);
    }
  }
  const acc=new Float32Array(NN).fill(1);
  for(let k=cnt-1;k>=0;k--){const c=order[k],d=down[c];if(d>=0)acc[d]+=acc[c]}
  const srt=Float32Array.from(acc).sort(),TR=Math.max(220,srt[Math.floor(NN*.983)]);
  /* lagos: depressões preenchidas, só as grandes */
  const lake=new Uint8Array(NN),lab=new Uint8Array(NN);
