  for(let c=0;c<NN;c++)if(lake[c]&&!lab[c]){
    const comp=[c];lab[c]=1;
    for(let k=0;k<comp.length;k++){const q=comp[k],qi=q%N,qj=(q/N)|0;
      for(const [a,b] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=qi+a,y=qj+b;if(x<0||y<0||x>=N||y>=N)continue;const n=y*N+x;if(lake[n]&&!lab[n]){lab[n]=1;comp.push(n)}}}
    if(comp.length<60)for(const q of comp)lake[q]=0;else lakeList.push({id:lakeList.length+1,cells:comp,water:[]});
  }
  for(let c=0;c<NN;c++)if(lake[c])FL[c]=1;
  /* rios: largura cresce com a vazão; correnteza segue o rumo do escoamento */
  const stamp=(ci,cj,R,dx,dy,m)=>{const r=Math.ceil(R);
    for(let b=-r;b<=r;b++)for(let a=-r;a<=r;a++){const x=ci+a,y=cj+b;if(x<0||y<0||x>=N||y>=N)continue;
      const v=1-Math.hypot(a,b)/R,o=y*N+x;if(v>FL[o]){FL[o]=v;FX[o]=dx*m;FY[o]=dy*m}}};
  for(let c=0;c<NN;c++){
    if(acc[c]<=TR||lake[c])continue;
    const ci=c%N,cj=(c/N)|0,d=down[c];let dx=0,dy=0;
    if(d>=0){dx=(d%N)-ci;dy=((d/N)|0)-cj;const l=Math.hypot(dx,dy);dx/=l;dy/=l}
    const q=Math.log10(acc[c]/TR+1),rv=.8+2.6*q,wb=Math.min(2.8,rv*.45);   // rios mais largos e sinuosos
    const ox=Math.round((vn(ci/9,cj/9,SEED+31)-.5)*2*wb),oy=Math.round((vn(ci/9,cj/9,SEED+32)-.5)*2*wb);
    stamp(ci+ox,cj+oy,Math.max(3,rv*2+.6),dx,dy,Math.min(30,8+10*q));
  }
  /* nascentes: cabeceiras dos rios (sem rio a montante) viram uma pequena poça borbulhante */
  for(let c=0;c<NN;c++){
    if(acc[c]<=TR||lake[c])continue;
    const ci=c%N,cj=(c/N)|0;if(Math.min(ci,cj,N-1-ci,N-1-cj)<16)continue;
    let up=false;
    for(let dj=-1;dj<=1&&!up;dj++)for(let di=-1;di<=1;di++){const x=ci+di,y=cj+dj;if((!di&&!dj)||x<0||y<0||x>=N||y>=N)continue;const n=y*N+x;if(down[n]===c&&acc[n]>TR){up=true;break}}
    if(up)continue;
    stamp(ci,cj,3.2,0,0,0);springs.push({x:(ci+.5)*G,y:(cj+.5)*G});
  }
  for(let c=0;c<NN;c++){const i=c%N,j=(c/N)|0,e=Math.min(i,j,N-1-i,N-1-j);FL[c]*=sst(9,13,e)}
  blur3(FL);blur3(FX);blur3(FY);
  for(const L of lakeList)for(const c of L.cells)LID[c]=L.id;
  {const add=[];for(let c=N+1;c<NN-N-1;c++){if(LID[c]||FL[c]<=.5)continue;const a=LID[c-1]||LID[c+1]||LID[c-N]||LID[c+N];if(a)add.push(c,a)}for(let k=0;k<add.length;k+=2)LID[add[k]]=add[k+1]}
  for(let c=0;c<NN;c++)if(LID[c]&&FL[c]>.8)lakeList[LID[c]-1].water.push(c);
  /* distância até a água (para a faixa de lama) */
  for(let o=0;o<NN;o++)DM[o]=FL[o]>.5?0:1e9;
  for(let j=0;j<N;j++)for(let i=0;i<N;i++){const k=j*N+i;let v=DM[k];
    if(i>0)v=Math.min(v,DM[k-1]+G);
    if(j>0){v=Math.min(v,DM[k-N]+G);if(i>0)v=Math.min(v,DM[k-N-1]+11.3);if(i<N-1)v=Math.min(v,DM[k-N+1]+11.3)}DM[k]=v}
  for(let j=N-1;j>=0;j--)for(let i=N-1;i>=0;i--){const k=j*N+i;let v=DM[k];
    if(i<N-1)v=Math.min(v,DM[k+1]+G);
    if(j<N-1){v=Math.min(v,DM[k+N]+G);if(i<N-1)v=Math.min(v,DM[k+N+1]+11.3);if(i>0)v=Math.min(v,DM[k+N-1]+11.3)}DM[k]=v}
  /* pedras ao redor das nascentes */
  for(const s of springs)for(let k=0;k<6;k++){const a=k*1.047+hs(s.x|0,s.y|0,5)*2,r=17+hs(k,s.x|0,6)*7,x=s.x+Math.cos(a)*r,y=s.y+Math.sin(a)*r*.8;if(terr(x,y)!==WATER)springRocks.push({x,y})}
  dirtAreas();
  /* ponto de partida: na terra firme, perto de um rio médio */
  let best=-1,bd=1e18;
