  const first=cand.find(c=>Math.hypot(c.x-spawn.x,c.y-spawn.y)>70&&Math.hypot(c.x-spawn.x,c.y-spawn.y)<900);
  const ord=cand.slice().sort((a,b)=>(hs(a.k,3,SEED+121)-(a.riv?.6:0))-(hs(b.k,3,SEED+121)-(b.riv?.6:0)));if(first)ord.unshift(first);
