    if(!st.arr){st.to=(st.to===undefined?40:st.to)-dt;const d=stepTo(a,st.x,st.y,(a.kid?34:40)*a.spd,dt,a.role==='play'&&a.kid,st.s);if(d<=st.s+.6||st.to<=0){st.arr=1;st.w0=st.w||0;st.fn&&st.fn()}}
    else{st.w0-=dt;if(st.w0<=0){a.q.shift();st.f2&&st.f2()}}
