function drawVilMud(camX,camY){for(const V of vils){if(V.x<camX-175||V.x>camX+W+175||V.y<camY-125||V.y>camY+H+135)continue;const s=vilMud(V);g.drawImage(s,Math.round(V.x-camX-s.width/2),Math.round(V.y+20-camY-s.height/2))}}
let NTc=null,NTx=null;
function drawNight(camX,camY){
  const d=dkv();if(d<.005)return;
  if(d<.65){g.fillStyle='rgba(255,110,40,'+(.16*Math.sin(d/.65*Math.PI)).toFixed(3)+')';g.fillRect(0,0,W,H)}
  if(!NTc||NTc.width!==W||NTc.height!==H){NTc=document.createElement('canvas');NTc.width=W;NTc.height=H;NTx=NTc.getContext('2d')}
  const x=NTx,fl=1+Math.sin(PT*9)*.04+Math.sin(PT*5.3)*.03;
  x.globalCompositeOperation='source-over';x.clearRect(0,0,W,H);x.fillStyle='rgba(6,10,46,'+(.78*d).toFixed(3)+')';x.fillRect(0,0,W,H);
  x.globalCompositeOperation='destination-out';
  const L=[[W/2,H/2-8,34]];for(const V of vils){const sx=V.fx-camX,sy=V.fy-camY-6;if(sx>-130&&sx<W+130&&sy>-130&&sy<H+130)L.push([sx,sy,100*fl])}
  for(const[sx,sy,R]of L){const gr=x.createRadialGradient(sx,sy,2,sx,sy,R);gr.addColorStop(0,'rgba(0,0,0,1)');gr.addColorStop(.5,'rgba(0,0,0,.6)');gr.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=gr;x.fillRect(sx-R,sy-R,R*2,R*2)}
  g.drawImage(NTc,0,0);
  g.globalCompositeOperation='lighter';
  for(const[sx,sy,R]of L.slice(1)){const gr=g.createRadialGradient(sx,sy,2,sx,sy,R*.75);gr.addColorStop(0,'rgba(255,150,50,'+(.34*d).toFixed(3)+')');gr.addColorStop(1,'rgba(255,90,20,0)');g.fillStyle=gr;g.fillRect(sx-R,sy-R,R*2,R*2)}
  g.globalCompositeOperation='source-over'}
/* ================= SAMAÚMA: frutos caem · TAMANDUÁ · JACARÉ ================= */
const SAMHANG=25,sfruits=[];
const SAMPOD=mkc(7,5,c=>{ell(3,2,3,2,'#8a6a1c',c);ell(3,2,2,1,'#e0bf46',c);R_(c,2,1,2,1,'#fff0a0',c);R_(c,4,3,1,1,'#c99a2a')});
function dropSam(s){let x=s.x+(Math.random()-.5)*48,y=s.y+4+Math.random()*18;if(!okW(x,y)){x=s.x+(Math.random()-.5)*16;y=s.y+12}
  if(sfruits.length>1500){const k=sfruits.findIndex(f=>f.landed);if(k>=0)sfruits.splice(k,1)}
  sfruits.push({x,y,z:60+Math.random()*34,vz:0,age:0,landed:false,tree:s})}
function tickSam(s,dt){s.age+=dt;
  if(s.age<TUNE.SAM_T)return;
  if(s.rem==null){s.rem=20+((Math.random()*11)|0);s.dtm=Math.random()*3}   // 20 a 30 sementes
  s.dtm-=dt;
  if(s.dtm<=0&&s.rem>0){dropSam(s);s.rem--;s.dtm=1.5+Math.random()*5}      // uma de cada vez
  if(s.rem<=0){s.rem=null;s.age=-60}}                                       // pé fica sem fruto e descansa
function updSamFruits(dt){
  for(let i=sfruits.length-1;i>=0;i--){const f=sfruits[i];
    if(!f.landed){f.vz-=GRAV*.55*dt;f.z+=f.vz*dt;if(f.z<=0){f.z=0;f.landed=true}}
    else{if(started&&Math.hypot(p.x-f.x,p.y-f.y)<13&&addItem('pod',1)){sfruits.splice(i,1);say('+1 Semente de samaúma');continue}f.age+=dt;if(f.age>260)sfruits.splice(i,1)}}}
function drawSamPod(f,sx,sy){const a=f.landed&&f.age>200?Math.max(.3,1-(f.age-200)/60):1;g.globalAlpha=a;g.drawImage(SAMPOD,sx-3,sy-5-Math.round(f.z));g.globalAlpha=1}

/* ---- tamanduá-bandeira (sua folha de sprites; sem K e G) ---- */
const ANTS=new Image();ANTS.src='data:image/png;base64,';
const ACW=46,ACH=49,AFEET=39,AROW={walk:{r:0,l:1,u:2,d:3},eat:{r:4,l:5,d:6},lie:{r:7,l:8,d:9}};
const anteaters=[];
function initAnteaters(){
  const list=sams.filter((s,i)=>i%11===0);
  for(const s of list){
    let hx=s.x+16,hy=s.y+7;if(!okW(hx,hy)){hx=s.x-16;hy=s.y+7}if(!okW(hx,hy)){hx=s.x;hy=s.y+11}
    anteaters.push({x:hx,y:hy,home:{x:hx,y:hy},tree:s,dir:'d',f4:null,t:Math.random()*9,dist:0,mv:false,mode:'wait',w:6+Math.random()*30,ld:Math.random()<.5?'l':'r',ed:'r',sg:1,blk:0,hill:null,trips:0,eatT:0,chk:0,fr:null})}
}
function moveW(a,tx,ty,v,dt){
  const dx=tx-a.x,dy=ty-a.y,d=Math.hypot(dx,dy);if(d<1.5){a.mv=false;return d}
  const s=Math.min(v*dt,d),an=Math.atan2(dy,dx),sg=a.sg||1;
  for(const da of[0,.6*sg,-.6*sg,1.2*sg,-1.2*sg,1.9*sg,-1.9*sg]){const c=Math.cos(an+da),n=Math.sin(an+da),nx=a.x+c*s,ny=a.y+n*s;
    if(okW(nx,ny)){a.x=nx;a.y=ny;a.dist+=s;a.mv=true;smoothDir(a,c,n,dt);if(da)a.sg=da>0?1:-1;return d}}
  a.mv=false;return d}
function antFruit(a){let b=null,bd=1e9;for(const f of sfruits)if(f.landed&&f.tree===a.tree){const d=Math.hypot(f.x-a.x,f.y-a.y);if(d<bd){bd=d;b=f}}return b}
function antHill(a){const c=HILLS.filter(h=>Math.hypot(h.x-a.tree.x,h.y-a.tree.y)<900&&h!==a.hill).sort((p,q)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(q.x-a.x,q.y-a.y)).slice(0,5);
  return c.length?c[(Math.random()*c.length)|0]:null}
function updAnteater(a,dt){
  a.t+=dt;a.mv=false;a.chk-=dt;const m=a.mode;
  if(m!=='toFruit'&&m!=='eatFruit'&&m!=='wait'&&a.chk<=0){a.chk=2;const f=antFruit(a);if(f){a.fr=f;a.mode='toFruit';a.blk=0;return}}   // fruto caiu: volta correndo
  if(m==='wait'){
    if(a.chk<=0){a.chk=1.5;const f=antFruit(a);if(f){a.fr=f;a.mode='toFruit';a.blk=0;return}}
    a.w-=dt;if(a.w<=0){const h=antHill(a);if(h){a.hill=h;a.trips=1+((Math.random()*2)|0);a.mode='toHill';a.blk=0}else a.w=30}
    return}
  if(m==='toFruit'){const f=a.fr;if(!f||!sfruits.includes(f)){a.mode='back';a.blk=0;return}
    const d=moveW(a,f.x,f.y+2,22,dt);if(d<3){a.mode='eatFruit';a.eatT=3.6;a.ed=f.x>=a.x?'r':'l'}
    else if(!a.mv){a.blk+=dt;if(a.blk>6){a.mode='back';a.blk=0}}else a.blk=0;return}
  if(m==='eatFruit'){a.eatT-=dt;if(a.eatT<=0){const i=sfruits.indexOf(a.fr);if(i>=0)sfruits.splice(i,1);a.fr=null;a.mode=antFruit(a)?'toFruit':'back';if(a.mode==='toFruit')a.fr=antFruit(a);a.blk=0}return}
  if(m==='toHill'){const h=a.hill,d=moveW(a,h.x,h.y+7,20,dt);
    if(d<4){a.mode='eatAnts';a.eatT=9+Math.random()*5;a.ed=h.x>=a.x?'r':'l'}
    else if(!a.mv){a.blk+=dt;if(a.blk>6){a.mode='back';a.blk=0}}else a.blk=0;return}
  if(m==='eatAnts'){a.eatT-=dt;if(a.eatT<=0){a.trips--;const h=a.trips>0?antHill(a):null;if(h){a.hill=h;a.mode='toHill'}else a.mode='back';a.blk=0}return}
  if(m==='back'){const d=moveW(a,a.home.x,a.home.y,22,dt);
    if(d<3){a.mode='wait';a.w=30+Math.random()*30;a.ld=Math.random()<.5?'l':'r';a.dist=0}
    else if(!a.mv){a.blk+=dt;if(a.blk>8){a.x=a.home.x;a.y=a.home.y;a.blk=0}}else a.blk=0}
}
function updAnteaters(dt){for(const a of anteaters){if(near(a,800)){updAnteater(a,dt+(a.acc||0));a.acc=0}else{a.acc=(a.acc||0)+dt;if(a.acc>=.3){updAnteater(a,a.acc);a.acc=0}}}}
function drawAnt(a,sx,sy){
  let row,f;const m=a.mode;
  if(m==='wait'){row=AROW.lie[a.ld];f=Math.floor(a.t*1.1)%3}
  else if(m==='eatFruit'||m==='eatAnts'){row=AROW.eat[a.ed];f=Math.floor(a.t*3.5)%3}
  else{const d=face4(a);row=AROW.walk[d];f=a.mv?Math.floor(a.dist/5)%3:0}
  if(ANTS.complete)g.drawImage(ANTS,f*ACW,row*ACH,ACW,ACH,sx-(ACW>>1),sy-AFEET,ACW,ACH)}

/* ---- jacaré (sua folha: nadando e correndo; sem as animações de comer) ---- */
const CRS=new Image();CRS.src='data:image/png;base64,';
const CRN={u:6,d:6,l:8,r:8},CRR={swim:{u:0,d:1,l:2,r:3},run:{u:4,d:5,l:6,r:7}};
const crocs=[];
function initCrocs(){
  for(const L of lakeList){L.crocs=[];L.mt=200;if(!L.frogs||L.water.length<90)continue;
    const n=L.water.length>420?2:1;
    for(let k=0;k<n;k++){const c0=L.water[(Math.random()*L.water.length)|0],x=(c0%N+.5)*G,y=(((c0/N)|0)+.5)*G;
      const C={L,x,y,home:{x,y},dir:'r',f4:null,t:Math.random()*9,mode:'lurk',sub:1,subT:1,st:4+Math.random()*8,mv:false,dist:0,tx:null,ty:0,cd:20+Math.random()*40,bt:50+Math.random()*80,tg:null,et:0,dg:0,bk:0,sg:1,stk:0,ra:0};
      L.crocs.push(C);crocs.push(C)}}
}
function moveCroc(C,tx,ty,v,dt){
  const dx=tx-C.x,dy=ty-C.y,d=Math.hypot(dx,dy);if(d<1.5){C.mv=false;return d}
  const s=Math.min(v*dt,d),an=Math.atan2(dy,dx),sg=C.sg;
  for(const da of[0,.6*sg,-.6*sg,1.2*sg,-1.2*sg,1.9*sg,-1.9*sg]){const c=Math.cos(an+da),n=Math.sin(an+da),nx=C.x+c*s,ny=C.y+n*s;
    if(okFrog(nx,ny,C.L)){C.x=nx;C.y=ny;C.dist+=s;C.mv=true;smoothDir(C,c,n,dt);if(da)C.sg=da>0?1:-1;return d}}
  C.mv=false;return d}
function crocPrey(C){let b=null,bd=120;for(const F of C.L.frogs){if(F.sex!=='m'||F.jump)continue;const d=Math.hypot(F.x-C.x,F.y-C.y);if(d<bd){bd=d;b=F}}return b}   // só sapos machos
function updCroc(C,dt){
  const L=C.L,m=C.mode;C.t+=dt;C.mv=false;C.cd-=dt;C.bt-=dt;
  C.sub+=(C.subT-C.sub)*Math.min(1,dt*1.6);
  if(m==='lurk'){
    C.st-=dt;if(C.st<=0){C.subT=C.subT>.5?0:1;C.st=C.subT?10+Math.random()*10:8+Math.random()*6}   // sobe à superfície e desce de novo
    if(C.tx==null||Math.hypot(C.tx-C.x,C.ty-C.y)<4||(C.stk+=dt)>14){const a=Math.random()*6.283,r=15+Math.random()*60,x=C.home.x+Math.cos(a)*r,y=C.home.y+Math.sin(a)*r;C.stk=0;if(terr(x,y)===WATER&&okFrog(x,y,L)){C.tx=x;C.ty=y}else{C.tx=C.home.x;C.ty=C.home.y}}
    moveCroc(C,C.tx,C.ty,C.subT?7:11,dt);
    if(C.cd<=0){const F=crocPrey(C);if(F){C.tg=F;C.mode='hunt';C.stk=0;C.subT=.85;return}C.cd=4}
    if(C.bt<=0&&sched()==='day'&&dkv()<.3){const e=exitPoint(L,C.x,C.y,16);if(e){C.bx=e.x;C.by=e.y;C.mode='toBask';C.subT=0;C.stk=0}else C.bt=60}
    return}
  if(m==='hunt'){const F=C.tg;C.stk+=dt;
    if(!F||!L.frogs.includes(F)||C.stk>25){C.tg=null;C.mode='return';C.cd=40;return}
    const d=moveCroc(C,F.x,F.y,34,dt);if(d<30)C.subT=0;
    if(d<10){C.mode='eat';C.et=0;C.subT=0;C.dir=dir8(F.x-C.x,F.y-C.y);C.hx=F.x-C.x;C.hy=F.y-C.y}
    else if(!C.mv&&d>12&&C.stk>4){C.tg=null;C.mode='return'}
    return}
  if(m==='eat'){C.et+=dt;
    if(C.tg&&C.et>.55){const i=L.frogs.indexOf(C.tg);if(i>=0){L.frogs.splice(i,1);splash(C.tg.x,C.tg.y,10,.8);rings.push({x:C.tg.x,y:C.tg.y,t:0})}C.tg=null}
    if(C.et>1.7){C.mode='digest';C.dg=6+Math.random()*5}
    return}
  if(m==='digest'){C.dg-=dt;if(C.dg<=0)C.mode='return';return}   // fica parado digerindo
  if(m==='return'){const d=moveCroc(C,C.home.x,C.home.y,16,dt);C.subT=d<20?.8:0;
    if(d<5){C.mode='lurk';C.cd=90+Math.random()*70;C.st=6;C.tx=null;C.stk=0}
    else if(!C.mv){C.stk+=dt;if(C.stk>6){C.x=C.home.x;C.y=C.home.y;C.stk=0}}else C.stk=0;return}
  if(m==='toBask'){const d=moveCroc(C,C.bx,C.by,16,dt);
    if(d<4){C.mode='bask';C.bk=16+Math.random()*22;C.dir=C.dir}
    else if(!C.mv){C.stk+=dt;if(C.stk>8){C.mode='return'}}else C.stk=0;
    if(sched()!=='day')C.mode='return';return}
  if(m==='bask'){C.bk-=dt;if(C.bk<=0||sched()!=='day'){C.mode='return';C.bt=100+Math.random()*120}}   // toma sol na margem
}
function updateCrocs(dt){
  for(const C of crocs)updCroc(C,dt);
  for(const L of lakeList){if(!L.crocs||!L.crocs.length||!L.frogs)continue;
    if(!L.frogs.some(F=>F.sex==='m')&&L.frogs.some(F=>F.sex==='f')){L.mt-=dt;if(L.mt<=0){L.mt=240;const pt=shorePoint(L);if(pt)L.frogs.push(newFrog(L,pt.x,pt.y,'m',true))}}}   // chega um macho novo
  for(const C of crocs)if(C.sub<.5&&C.mv&&terr(C.x,C.y)===WATER&&Math.random()<dt*1.2)rings.push({x:C.x,y:C.y,t:.2})
}
function drawCroc(C,sx,sy,t){
  if(!CRS.complete)return;
  const inW=terr(C.x,C.y)===WATER,d=face4(C),m=C.mode,n=CRN[d];let f=0;
  if(inW)f=Math.floor(t*(C.mv?9:3))%n;
  else f=C.mv&&m!=='bask'?Math.floor(C.dist/3)%n:0;
  const row=CRR[inW?'swim':'run'][d];
  if(inW){
    g.globalAlpha=Math.max(.16,1-C.sub*.9);g.drawImage(CRS,f*64,row*64,64,64,sx-32,sy-33,64,64);g.globalAlpha=1;
    if(C.sub>.55){const ex=d==='r'?19:d==='l'?-19:0,ey=d==='d'?19:d==='u'?-19:-2;g.fillStyle='#e2c340';g.fillRect(sx+ex-2,sy+ey,1,1);g.fillRect(sx+ex+2,sy+ey,1,1)}}
  else g.drawImage(CRS,f*64,row*64,64,64,sx-32,sy-36,64,64);
}
/* ================= INVENTÁRIO / HOTBAR ================= */
const INV={hot:Array(5).fill(null),store:Array(32).fill(null),craft:Array(9).fill(null),armor:Array(4).fill(null),sel:0,held:null};
let invOpen=false;
const ITEMS={pod:{name:'Semente de samaúma',icon:SAMPOD.toDataURL()},
  stick:{name:'Graveto',icon:'data:image/png;base64,',smooth:1},
  knife:{name:'Faquinha',icon:'data:image/png;base64,',smooth:1}};
const UM={"W": 2108, "H": 629, "xs": [652, 754, 856, 958, 1059, 1161, 1262, 1365], "ys": [160, 249, 337, 425], "sw": 92, "sh": 78, "craft": [[1595, 149, 76, 75], [1693, 149, 76, 75], [1791, 149, 76, 75], [1595, 245, 76, 75], [1693, 245, 76, 75], [1791, 245, 76, 75], [1595, 341, 76, 75], [1693, 341, 76, 75], [1791, 341, 76, 75]], "out": [1681, 487, 98, 97], "armor": [[503, 184, 57, 49], [503, 242, 57, 49], [503, 298, 57, 49], [503, 354, 57, 49]], "por": [272, 186, 210, 229], "stat": [44, 440, 509, 59]};
const UIG={hot:{W:160,H:611,x:33,ys:[34,148,261,375,487],w:91,h:84},
  all:{W:UM.W,H:UM.H}};
const SLOTS={hot:[],store:[],craft:[],out:[],armor:[]};
function mkSlot(parent,arr,i,Gw,Gh,x,y,w,h){const d=document.createElement('div');d.className='sl';
  d.style.cssText=`left:${x/Gw*100}%;top:${y/Gh*100}%;width:${w/Gw*100}%;height:${h/Gh*100}%`;
  d.addEventListener('click',e=>{e.stopPropagation();slotClick(arr,i)});
  d.addEventListener('contextmenu',e=>{e.preventDefault();e.stopPropagation();slotOne(arr,i)});
  parent.appendChild(d);SLOTS[arr][i]=d}
(function buildUI(){
  const hb=document.getElementById('hbw'),sb=document.getElementById('invBox'),H=UIG.hot;
  H.ys.forEach((y,i)=>mkSlot(hb,'hot',i,H.W,H.H,H.x,y,H.w,H.h));
  for(let r=0;r<4;r++)UM.xs.forEach((x,c)=>mkSlot(sb,'store',r*8+c,UM.W,UM.H,x,UM.ys[r],UM.sw,UM.sh));
  UM.craft.forEach((q,i)=>mkSlot(sb,'craft',i,UM.W,UM.H,q[0],q[1],q[2],q[3]));
  mkSlot(sb,'out',0,UM.W,UM.H,UM.out[0],UM.out[1],UM.out[2],UM.out[3]);
  UM.armor.forEach((q,i)=>mkSlot(sb,'armor',i,UM.W,UM.H,q[0],q[1],q[2],q[3]));
  const ov=(id,q,html)=>{const d=document.createElement('div');d.id=id;d.className='ov';d.style.cssText=`left:${q[0]/UM.W*100}%;top:${q[1]/UM.H*100}%;width:${q[2]/UM.W*100}%;height:${q[3]/UM.H*100}%`;d.innerHTML=html;sb.appendChild(d);return d};
  ov('portrait',UM.por,'<canvas id="pcv" width="32" height="32"></canvas>');
  ov('stat',UM.stat,'<div><span class="lb">ARMAZENAMENTO</span><span class="vl" id="stV">0/41</span><span class="bar"><i id="stB"></i></span></div><div><span class="lb">PROTEÇÃO</span><span class="vl" id="prV">0</span></div>');
  document.getElementById('bagBtn').addEventListener('click',toggleInv);
  document.getElementById('invOv').addEventListener('click',e=>{if(e.target.id==='invOv'&&invOpen)toggleInv()});
  addEventListener('resize',layoutInv);renderInv();layoutInv()})();
function layoutInv(){
  const ov=document.getElementById('invOv'),box=document.getElementById('invBox'),hb=document.getElementById('hotbar');
  const hh=18,rw=hb.offsetWidth+14,aw=innerWidth-16-rw,ah=innerHeight-hh-16;
  const s=Math.min(aw/UM.W,ah/UM.H);box.style.width=Math.max(160,UM.W*s)+'px';box.style.height=Math.max(70,UM.H*s)+'px';box.style.setProperty('--s',s.toFixed(3));
  ov.style.paddingBottom=hh+'px';ov.style.paddingRight=(rw+8)+'px'}
/* receita: pedra EM CIMA, graveto EM BAIXO (mesma coluna, em qualquer posição da grade) */
function recipe(){
  const C=INV.craft,filled=[];C.forEach((it,i)=>{if(it)filled.push(i)});
  if(filled.length!==2)return null;
  for(let r=0;r<2;r++)for(let c=0;c<3;c++){const t=C[r*3+c],u=C[(r+1)*3+c];
    if(t&&u&&t.id==='stone'&&u.id==='stick')return{id:'knife',n:1,use:[r*3+c,(r+1)*3+c]}}
  return null}
function renderInv(){
  const paint=(el,it,sel,hold,ghost)=>{if(!el)return;el.className='sl'+(sel?' sel':'')+(hold?' hold':'');
    el.innerHTML=it?`<img class="ic" ${ITEMS[it.id].smooth?'style="image-rendering:auto" ':''}src="${ITEMS[it.id].icon}" alt="">${it.n>1?`<i class="n">${it.n}</i>`:''}`:''};
  const H=INV.held;
  INV.hot.forEach((it,i)=>paint(SLOTS.hot[i],it,i===INV.sel,H&&H.a==='hot'&&H.i===i));
  INV.store.forEach((it,i)=>paint(SLOTS.store[i],it,false,H&&H.a==='store'&&H.i===i));
  INV.craft.forEach((it,i)=>paint(SLOTS.craft[i],it,false,H&&H.a==='craft'&&H.i===i));
  INV.armor.forEach((it,i)=>paint(SLOTS.armor[i],it,false,H&&H.a==='armor'&&H.i===i));
  const rc=recipe();paint(SLOTS.out[0],rc?{id:rc.id,n:rc.n}:null,false,false);
  const tot=INV.hot.length+INV.store.length,used=INV.hot.concat(INV.store).filter(Boolean).length,sv=document.getElementById('stV');
  if(sv){sv.textContent=used+'/'+tot;const b=document.getElementById('stB');b.style.width=(used/tot*100)+'%';b.className=used>=tot?'full':'';document.getElementById('prV').textContent=protection()}
  paintPortrait();
  if(SLOTS.out[0])SLOTS.out[0].classList.toggle('ready',!!rc)}
function protection(){let n=0;for(const it of INV.armor)if(it&&ITEMS[it.id]&&ITEMS[it.id].prot)n+=ITEMS[it.id].prot;return n}
function paintPortrait(){const c=document.getElementById('pcv');if(!c||!sheet.complete||!sheet.naturalWidth)return;
  const x=c.getContext('2d');x.imageSmoothingEnabled=false;x.clearRect(0,0,32,32);x.drawImage(sheet,0,0,32,32,0,0,32,32)}   // sprite 1 (de frente)
sheet.addEventListener('load',()=>{try{paintPortrait()}catch(e){}});
function canAdd(id){for(const a of['hot','store'])for(const s of INV[a]){if(!s||(s.id===id&&s.n<64))return true}return false}
function doCraft(){
  const rc=recipe();if(!rc)return;
  if(!rc.use.every(k=>INV.craft[k]&&INV.craft[k].n>0))return;
  if(!addItem(rc.id,rc.n)){say('Mochila cheia!');return}
  for(const k of rc.use){const s=INV.craft[k];s.n--;if(s.n<=0)INV.craft[k]=null}
  INV.held=null;say('Você criou uma '+ITEMS[rc.id].name+'!');renderInv()}
function slotClick(a,i){
  if(a==='out'){doCraft();return}
  if(a==='hot'&&!invOpen){INV.sel=i;renderInv();const it=INV.hot[i];if(it)say(ITEMS[it.id].name);return}
  const h=INV.held;
  if(!h){if(INV[a][i]){INV.held={a,i};if(a==='hot')INV.sel=i;say(ITEMS[INV[a][i].id].name)}}
  else if(h.a===a&&h.i===i)INV.held=null;
  else{const A=INV[h.a],B=INV[a],x=A[h.i],y=B[i];
    const okP=(arr,it)=>arr!=='armor'||!it||ITEMS[it.id].armor!=null;
    if(!okP(a,x)||!okP(h.a,y)){say('Isso não é um equipamento');return}
    if(x&&y&&x.id===y.id){const mv=Math.min(64-y.n,x.n);y.n+=mv;x.n-=mv;if(x.n<=0)A[h.i]=null}else{A[h.i]=y;B[i]=x}
    INV.held=null}
  renderInv()}
/* botão direito / toque longo: move só 1 unidade do item selecionado */
function slotOne(a,i){
  if(a==='out'||a==='armor'||!invOpen)return;const h=INV.held;if(!h)return;
  if(h.a===a&&h.i===i)return;
  const A=INV[h.a],B=INV[a],x=A[h.i],y=B[i];if(!x)return;
  if(y&&y.id!==x.id)return;if(y&&y.n>=64)return;
  if(y)y.n++;else B[i]={id:x.id,n:1};
  x.n--;if(x.n<=0){A[h.i]=null;INV.held=null}
  renderInv()}
function returnCraft(){for(let i=0;i<9;i++){const s=INV.craft[i];if(s&&addItem(s.id,s.n))INV.craft[i]=null}}
function toggleInv(){if(pDead)return;invOpen=!invOpen;INV.held=null;if(!invOpen)returnCraft();releaseAll();layoutInv();document.getElementById('invOv').classList.toggle('open',invOpen);renderInv()}
function addItem(id,n){
  for(const a of['hot','store'])for(const s of INV[a])if(s&&s.id===id&&s.n<64){const m=Math.min(64-s.n,n);s.n+=m;n-=m;if(n<=0){renderInv();return true}}
  if(n>0&&!INV.hot[INV.sel]){const m=Math.min(64,n);INV.hot[INV.sel]={id,n:m};n-=m;if(n<=0){renderInv();return true}}   // item novo vai direto para a mão
  for(const a of['hot','store'])for(let i=0;i<INV[a].length&&n>0;i++)if(!INV[a][i]){const m=Math.min(64,n);INV[a][i]={id,n:m};n-=m;if(n<=0){renderInv();return true}}
  renderInv();return false}
function pickSlot(i){INV.sel=i;renderInv();const it=INV.hot[i];if(it)say(ITEMS[it.id].name)}
addEventListener('wheel',e=>{if(!started||invOpen)return;pickSlot((INV.sel+(e.deltaY>0?1:4))%5)},{passive:true});
addEventListener('keydown',e=>{if(!started)return;
  if(e.code==='KeyI'||e.code==='KeyE'||e.code==='Tab'){e.preventDefault();toggleInv()}
  else if(e.code==='Escape'&&invOpen)toggleInv();
  else if(/^Digit[1-5]$/.test(e.code)&&!invOpen){pickSlot(+e.code.slice(5)-1)}
  else if(e.code==='KeyQ'&&!invOpen){pickSlot((INV.sel+4)%5)}
  else if(e.code==='KeyR'&&!invOpen){pickSlot((INV.sel+1)%5)}});
/* ================= PEDRAS · GARÇAS ================= */
const RIMG=new Image();RIMG.src='data:image/png;base64,';
const RMETA=[[0, 0, 14, 10], [16, 0, 16, 11], [34, 0, 21, 16], [57, 0, 22, 13], [81, 0, 24, 20], [107, 0, 29, 24], [138, 0, 28, 23], [168, 0, 23, 22], [193, 0, 28, 16], [223, 0, 20, 29], [245, 0, 27, 21], [0, 31, 27, 22], [29, 31, 27, 19], [58, 31, 29, 22], [89, 31, 25, 19], [116, 31, 24, 22], [142, 31, 27, 19], [171, 31, 26, 24], [199, 31, 22, 17], [223, 31, 17, 23], [242, 31, 24, 22], [268, 31, 25, 22], [0, 57, 28, 19], [30, 57, 34, 16]];
const STONEI=new Image();STONEI.src='data:image/png;base64,';
ITEMS.stone={name:'Pedra',icon:STONEI.src};
const rocksL=[],rockGrid=new Map(),gitems=[],rchips=[];
const rgk=(x,y)=>((x/64)|0)*1000+((y/64)|0);
function rockAdd(r){const k=rgk(r.x,r.y);let a=rockGrid.get(k);if(!a)rockGrid.set(k,a=[]);a.push(r);rocksL.push(r)}
function rockDel(r){const a=rockGrid.get(rgk(r.x,r.y));if(a){const i=a.indexOf(r);if(i>=0)a.splice(i,1)}const j=rocksL.indexOf(r);if(j>=0)rocksL.splice(j,1)}
function rockHit(x,y){const cx=(x/64)|0,cy=(y/64)|0;
  for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++){const L=rockGrid.get((cx+a)*1000+(cy+b));if(!L)continue;
    for(const r of L){const ex=(x-r.x)/r.cr,ey=(y-(r.y-3))/(r.cr*.65);if(ex*ex+ey*ey<1)return true}}return false}
function rockPush(){const cx=(p.x/64)|0,cy=(p.y/64)|0;
  for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++){const L=rockGrid.get((cx+a)*1000+(cy+b));if(!L)continue;
    for(const r of L){const ex=p.x-r.x,ey=p.y-(r.y-3),e=Math.hypot(ex/r.cr,ey/(r.cr*.65));
      if(e<1&&p.z<14){const k=e||.01;p.x=r.x+ex/k;p.y=r.y-3+ey/k}}}}
function mkRocks(){
  const wt=RMETA.map(m=>m[2]<28?3:m[2]<40?2:1),tot=wt.reduce((a,b)=>a+b,0);
  let n=0,tries=0;
  while(n<120&&tries<9000){tries++;
    const x=RIM+30+Math.random()*(WS-2*RIM-60),y=RIM+30+Math.random()*(WS-2*RIM-60),t=terr(x,y);
    if(t!==GRASS&&t!==DIRT)continue;
    if(![[12,0],[-12,0],[0,9],[0,-9]].every(([a,b])=>{const u=terr(x+a,y+b);return u===GRASS||u===DIRT}))continue;
    if(vilBlock(x,y)||Math.hypot(x-spawn.x,y-spawn.y)<90)continue;
    if(HILLS.some(h=>Math.hypot(h.x-x,h.y-y)<60))continue;
    if(sams.some(s=>Math.hypot(s.x-x,s.y-y)<36))continue;
    if(rocksL.some(r=>Math.hypot(r.x-x,r.y-y)<44))continue;
    let bad=false;const tx=Math.floor(x/T),ty=Math.floor(y/T);
    for(let a=-2;a<=2&&!bad;a++)for(let b=-2;b<=2&&!bad;b++){const v=tileObj(tx+a,ty+b);if(v&&(v.k===0||v.k===1||v.k===2))bad=true}
    if(bad)continue;
    let q=Math.random()*tot,i=0;while(q>wt[i]){q-=wt[i];i++}
    const m=RMETA[i],w=m[2],h=m[3],cr=Math.min(11,Math.max(4,w*.32));
    const cr_=[];for(let k=0;k<4;k++){let cx=w*(.25+Math.random()*.5),cy=h*(.25+Math.random()*.4);const seg=[];for(let s=0;s<3;s++){seg.push([cx,cy]);cx+=(Math.random()-.5)*w*.34;cy+=Math.random()*h*.22}seg.push([cx,cy]);cr_.push(seg)}
    rockAdd({x:Math.round(x),y:Math.round(y),i,w,h,cr,hits:0,shake:0,cd:0,brk:0,cracks:cr_});n++}
}
function line1(x0,y0,x1,y1,col){g.fillStyle=col;x0=Math.round(x0);y0=Math.round(y0);x1=Math.round(x1);y1=Math.round(y1);
  const dx=Math.abs(x1-x0),dy=-Math.abs(y1-y0),sx=x0<x1?1:-1,sy=y0<y1?1:-1;let e=dx+dy;
  for(let k=0;k<60;k++){g.fillRect(x0,y0,1,1);if(x0===x1&&y0===y1)break;const e2=2*e;if(e2>=dy){e+=dy;x0+=sx}if(e2<=dx){e+=dx;y0+=sy}}}
function chips(x,y,n){const C=['#6e6e68','#8c8c86','#4f9a2a','#3d7a1e','#3a3a36'];
  for(let i=0;i<n;i++){const a=Math.random()*6.283,v=25+Math.random()*45;rchips.push({x,y,z:4+Math.random()*8,vx:Math.cos(a)*v,vy:Math.sin(a)*v*.5,vz:50+Math.random()*60,t:0,c:C[(Math.random()*C.length)|0]})}}
function hitRockAt(x,y){
  let b=null;for(const r of rocksL){if(r.brk>0)continue;
    if(x>=r.x-r.w/2-3&&x<=r.x+r.w/2+3&&y>=r.y-r.h-3&&y<=r.y+4&&(!b||r.y>b.y))b=r}
  if(!b)return;
  if(Math.hypot(p.x-b.x,p.y-b.y)>34+b.w*.5){say('Chegue mais perto da pedra');return}
  if(b.cd>0)return;b.cd=.12;b.hits++;b.shake=.2;chips(b.x,b.y-b.h*.5,b.hits>=5?0:5);
  if(b.hits>=5){b.brk=.8;b.dropped=false;
    b.pcs=[];const cw=Math.ceil(b.w/3),ch=Math.ceil(b.h/2);
    for(let r=0;r<2;r++)for(let c=0;c<3;c++){const sx0=c*cw,sy0=r*ch,pw=Math.min(cw,b.w-sx0),ph=Math.min(ch,b.h-sy0);
      b.pcs.push({sx:sx0,sy:sy0,w:pw,h:ph,ox:0,oy:0,vx:(c-1)*38+(Math.random()-.5)*20,vy:-(40+Math.random()*50)+(r?30:0),rot:0})}
    chips(b.x,b.y-b.h*.5,16)}}
function updRocks(dt){
  for(const r of rocksL.slice()){r.cd-=dt;if(r.shake>0)r.shake-=dt;
    if(r.brk>0){r.brk-=dt;for(const q of r.pcs){q.vy+=300*dt;q.ox+=q.vx*dt;q.oy+=q.vy*dt}
      if(!r.dropped&&r.brk<.45){r.dropped=true;const n=r.w<28?1+((Math.random()*2)|0):r.w<38?2+((Math.random()*2)|0):3+((Math.random()*3)|0);
        for(let k=0;k<n;k++){const a=Math.random()*6.283,v=20+Math.random()*30;gitems.push({x:r.x,y:r.y,z:6,vz:70+Math.random()*50,vx:Math.cos(a)*v,vy:Math.sin(a)*v*.6,id:'stone',landed:false,age:0})}}
      if(r.brk<=0)rockDel(r)}}
  for(let i=gitems.length-1;i>=0;i--){const f=gitems[i];
    if(!f.landed){f.vz-=GRAV*dt;f.z+=f.vz*dt;const nx=f.x+f.vx*dt,ny=f.y+f.vy*dt;if(okA(nx,ny)){f.x=nx;f.y=ny}if(f.z<=0){f.z=0;f.landed=true}}
    else{f.age+=dt;const d=Math.hypot(p.x-f.x,p.y-f.y);
      if(started&&d<42&&p.z<10){const sp=Math.min(d,(d<14?150:70)*dt);f.x+=(p.x-f.x)/d*sp;f.y+=(p.y-f.y)/d*sp}   // ao passar por cima, a pedra vem até você
      if(started&&d<9&&p.z<10&&addItem(f.id,1)){say('+1 Pedra');gitems.splice(i,1);continue}
      if(f.age>600)gitems.splice(i,1)}}
  for(let i=rchips.length-1;i>=0;i--){const q=rchips[i];q.t+=dt;q.vz-=GRAV*dt;q.z+=q.vz*dt;q.x+=q.vx*dt;q.y+=q.vy*dt;if(q.z<=0||q.t>1)rchips.splice(i,1)}
}
function drawRock(r,sx,sy,t){const m=RMETA[r.i];
  if(r.brk>0){const a=Math.max(0,Math.min(1,r.brk/.4));g.globalAlpha=a;
    for(const q of r.pcs)g.drawImage(RIMG,m[0]+q.sx,m[1]+q.sy,q.w,q.h,Math.round(sx-r.w/2+q.sx+q.ox),Math.round(sy-r.h+2+q.sy+q.oy),q.w,q.h);
    g.globalAlpha=1;return}
  const dx=r.shake>0?Math.round(Math.sin(t*70)*1.6):0;
  g.drawImage(RIMG,m[0],m[1],m[2],m[3],sx-(r.w>>1)+dx,sy-r.h+2,r.w,r.h);
  for(let k=0;k<Math.min(4,r.hits);k++){const c=r.cracks[k],ox=sx-(r.w>>1)+dx,oy=sy-r.h+2;
    for(let s=0;s<c.length-1;s++)line1(ox+c[s][0],oy+c[s][1],ox+c[s+1][0],oy+c[s+1][1],'#15150f')}}
function drawGItem(f,sx,sy){g.drawImage(STONEI,sx-6,sy-9-Math.round(f.z),12,8)}
function drawRockFx(camX,camY){for(const q of rchips){g.fillStyle=q.c;g.fillRect(Math.round(q.x-camX),Math.round(q.y-camY-q.z),2,2)}}
cv.addEventListener('pointerdown',e=>{if(!started||invOpen||pDead||!worldReady)return;if(INV.hot[INV.sel])p.swing=.28;
  const r=cv.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W+cam.x,y=(e.clientY-r.top)/r.height*H+cam.y;if(!hitMedAt(x,y)&&!hitStickAt(x,y)&&!hitBoneAt(x,y)&&!useDust(x,y)&&!hitFruitTree(x,y)&&!useHerb())hitRockAt(x,y)});


