function leaveCave(){CV.mode=0;CV.M=null;const c=CV.cave;p.x=c.ex;p.y=c.my+14;p.face='down';p.z=0;CV.st='out';CV.t=0;CV.f=1;CVD=11;for(const k in keys)keys[k]=0}
function cvBlocked(x,y){const M=CV.M,w=(a,b)=>M.wall(Math.floor(a/CAVT),Math.floor(b/CAVT));
  if(w(x-4,y)||w(x+4,y)||w(x-4,y-3)||w(x+4,y-3))return true;
  for(const q of M.pool)if(((x-q.x)/(q.rx-2))**2+((y-q.y)/(q.ry-1))**2<1)return true;return false}
