  for(const t of acuris)if(t.x>camX-40&&t.x<camX+W+40&&t.y>camY-8&&t.y<camY+H+80)objs.push(t);
  for(const C of crocs)if(C.x>camX-40&&C.x<camX+W+40&&C.y>camY-20&&C.y<camY+H+40)objs.push({k:40,x:C.x,y:C.y,o:C});
  for(const a of anteaters)if(a.x>camX-40&&a.x<camX+W+40&&a.y>camY-10&&a.y<camY+H+60)objs.push({k:41,x:a.x,y:a.y,o:a});
