  for(const c of cats)if(c.x>camX-20&&c.x<camX+W+20&&c.y>camY-30&&c.y<camY+H+30)objs.push({k:82,x:c.x,y:(c.on>.05||c.st==='t')?c.b.y+1:c.y,o:c});
