for(const [c,id,v,x,y,w,h] of MATA_META){(MD[c][id]=MD[c][id]||[])[v]={x,y,w,h,id}}
const MW={
  tree:{17:3,18:3,19:3,20:3,21:3,22:2,24:2,25:2,26:2,27:2},
  rock:{0:.7,1:1.4,2:1.4,3:1.4,4:1.4,5:1.4,6:1.4,7:2.4,8:2.4,9:2.4,10:2.4,11:2.4,12:2.4,13:2.4,14:2.4,15:2.4,16:2.4,23:1.5},
  bush:{36:.6},plant:{}};
function wpick(cat){const ids=Object.keys(MD[cat]),w=ids.map(i=>MW[cat][i]||1);let q=Math.random()*w.reduce((a,b)=>a+b,0),k=0;while(q>w[k]&&k<ids.length-1){q-=w[k];k++}return +ids[k]}

/* densidade de mata: manchas grandes de floresta fechada e clareiras */
function FDN(x,y){return vn(x/170,y/170,SEED+77)*.66+vn(x/58,y/58,SEED+78)*.34}
const FLOORC=[14,50,30];
const mixC=(a,b,k)=>[(a[0]+(b[0]-a[0])*k)|0,(a[1]+(b[1]-a[1])*k)|0,(a[2]+(b[2]-a[2])*k)|0];
function shade(ids,dep,M,i,j,wx,wy){
  const c=shade0(ids,dep,M,i,j,wx,wy);
  if(ids[j*M+i]!==1)return c;
  const f=FDN(wx,wy);if(f<.5)return c;
  return mixC(c,FLOORC,Math.min(.4,(f-.5)*1.7));
}

/* ---- plantio ---- */
const MG=new Map();let MCOUNT=0;
const mgk=(x,y)=>((x/64)|0)*1000+((y/64)|0);
function mataAdd(m){const k=mgk(m.x,m.y);let a=MG.get(k);if(!a)MG.set(k,a=[]);a.push(m);MCOUNT++}
function mkM(cat,id,x,y,vi){
  const d=MD[cat][id],s=d[vi!=null&&d[vi]?vi:0],w=s.w,h=s.h;
  const m={k:90,x:Math.round(x),y:Math.round(y),cat,id,s,sw:Math.random()*6.28};
  if(cat==='tree'){m.sh=[Math.round(w*.16),Math.round(w*.3),5];m.cr=Math.max(4,Math.round(w*.085));m.amp=h*.04}
  else if(cat==='rock'){m.sh=[3,Math.round(w*.46),Math.max(3,Math.round(h*.1))];m.cr=Math.min(22,Math.max(4,Math.round(w*.31)))}
  else if(cat==='bush'){m.sh=[2,Math.round(w*.38),3];m.amp=.9}
  else{m.sh=[1,Math.round(w*.3),2];m.amp=1}
  return m}
function landOk(x,y,r){
  const t=terr(x,y);if(t!==GRASS&&t!==DIRT)return false;
  for(const [a,b] of [[r,0],[-r,0],[0,r*.7],[0,-r*.7]]){const u=terr(x+a,y+b);if(u!==GRASS&&u!==DIRT)return false}
  return true}
function mataNear(x,y,fn){const cx=(x/64)|0,cy=(y/64)|0;
  for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++){const L=MG.get((cx+a)*1000+(cy+b));if(!L)continue;for(const m of L)if(fn(m))return true}return false}
function mkMata(){
  MG.clear();MCOUNT=0;
  const areas=[];for(const A of [TAREAS,SAREAS])if(A)for(const a of A)if(a&&a.cx!==undefined)areas.push(a);
  const xmin=RIM+26,xmax=WS-RIM-26;
  const free=(x,y,rr)=>{
    if(x<xmin||y<xmin||x>xmax||y>xmax)return false;
    if(vilBlock(x,y))return false;
    if(Math.hypot(x-spawn.x,y-spawn.y)<rr.sp)return false;
    for(const a of areas)if(Math.hypot(a.cx-x,a.cy-y)<(a.r||40)+rr.ar)return false;
    for(const h of HILLS)if(Math.abs(h.x-x)<rr.hl&&Math.abs(h.y-y)<rr.hl)return false;
    for(const s of sams)if(Math.hypot(s.x-x,s.y-y)<rr.sm)return false;
    for(const c of cavesL)if(Math.hypot(c.x-x,c.y-y)<rr.cv)return false;
    for(const m of medL)if(Math.abs(m.x-x)<rr.md&&Math.abs(m.y-y)<rr.md)return false;
    return true};
  const R_BIG={sp:80,ar:26,hl:44,sm:56,cv:110,md:22},R_SM={sp:26,ar:4,hl:14,sm:30,cv:70,md:12};
  /* 1) pedras grandes e médias, em grupos */
  let n=0,tries=0;
  while(n<330&&tries++<30000){
    const x=xmin+Math.random()*(xmax-xmin),y=xmin+Math.random()*(xmax-xmin),f=FDN(x,y);
    if(Math.random()>.35+f*.9)continue;
    const id=wpick('rock'),d=MD.rock[id],w=d[0].w;
    if(!free(x,y,R_BIG)||!landOk(x,y,Math.min(14,w*.3)))continue;
    if(rocksL.some(r=>Math.hypot(r.x-x,r.y-y)<40)||trees2.some(r=>Math.hypot(r.x-x,r.y-y)<42))continue;
    if(mataNear(x,y,m=>m.cat==='rock'&&Math.abs(m.x-x)<(m.s.w+w)*.45&&Math.abs(m.y-y)<(m.s.h+d[0].h)*.3))continue;
    const m=mkM('rock',id,x,y,w>=44&&Math.random()<.3?1:0);mataAdd(m);const k=rgk(m.x,m.y);let a=rockGrid.get(k);if(!a)rockGrid.set(k,a=[]);a.push({x:m.x,y:m.y,cr:m.cr,mata:1});n++;
    if(w>=40)for(let q=0,c=(Math.random()*3)|0;q<c;q++){const a2=Math.random()*6.283,r2=w*.55+Math.random()*10,x2=x+Math.cos(a2)*r2,y2=y+Math.sin(a2)*r2*.5;
      if(!landOk(x2,y2,6)||!free(x2,y2,R_SM))continue;
      const sid=[10,11,12,14,16,9,7,23][(Math.random()*8)|0],sm=mkM('rock',sid,x2,y2,1);mataAdd(sm);const kk=rgk(sm.x,sm.y);let aa=rockGrid.get(kk);if(!aa)rockGrid.set(kk,aa=[]);aa.push({x:sm.x,y:sm.y,cr:Math.max(3,sm.cr-1),mata:1})}
  }
  /* 2) árvores: floresta fechada nas manchas densas */
  n=0;tries=0;
  while(n<2000&&tries++<140000){
    const x=xmin+Math.random()*(xmax-xmin),y=xmin+Math.random()*(xmax-xmin),f=FDN(x,y);
    if(Math.random()>.03+sst(.36,.6,f)*.97)continue;
    if(!free(x,y,R_BIG)||!landOk(x,y,10))continue;
    if(trees2.some(r=>Math.hypot(r.x-x,r.y-y)<40)||rocksL.some(r=>Math.hypot(r.x-x,r.y-y)<26))continue;
    if(mataNear(x,y,m=>(m.cat==='tree'&&((m.x-x)/(m.s.w*.34+7))**2+((m.y-y)/16)**2<1)||(m.cat==='rock'&&Math.abs(m.x-x)<m.s.w*.5+8&&Math.abs(m.y-y)<m.s.h*.3+6)))continue;
    const id=wpick('tree'),m=mkM('tree',id,x,y,Math.random()<(f>.55?.5:.35)?1:0);mataAdd(m);
    const k=rgk(m.x,m.y);let a=TRG.get(k);if(!a)TRG.set(k,a=[]);a.push({x:m.x,y:m.y,cr:m.cr,mata:1});n++}
  /* 3) arbustos em moitas (mais nas manchas de mata, junto de árvores e pedras) */
  n=0;tries=0;
  while(n<3000&&tries++<30000){
    const cx=xmin+Math.random()*(xmax-xmin),cy=xmin+Math.random()*(xmax-xmin),f=FDN(cx,cy);
    if(Math.random()>.1+sst(.3,.6,f)*.9)continue;
    const nb=3+((Math.random()*6)|0);
    for(let k=0;k<nb;k++){const a=Math.random()*6.283,r=3+Math.random()*34,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r*.75;
      if(!free(x,y,R_SM)||!landOk(x,y,5))continue;
      const id=wpick('bush'),w=MD.bush[id][0].w;
      if(mataNear(x,y,m=>(m.cat==='bush'&&Math.abs(m.x-x)<w*.55&&Math.abs(m.y-y)<7)||(m.cat==='tree'&&Math.abs(m.x-x)<m.cr+5&&Math.abs(m.y-y)<5)||(m.cat==='rock'&&Math.abs(m.x-x)<m.s.w*.45&&Math.abs(m.y-y)<m.s.h*.35)))continue;
      if(bushL.some(b=>Math.abs(b.x-x)<10&&Math.abs(b.y-y)<6))continue;
      mataAdd(mkM('bush',id,x,y,Math.random()<.45?1:0));n++}}
  /* 4) samambaias, capins e flores no sub-bosque */
  n=0;tries=0;
  while(n<6500&&tries++<40000){
    const cx=xmin+Math.random()*(xmax-xmin),cy=xmin+Math.random()*(xmax-xmin),f=FDN(cx,cy);
    if(Math.random()>.12+sst(.25,.55,f)*.88)continue;
    const nb=3+((Math.random()*8)|0);
    for(let k=0;k<nb;k++){const a=Math.random()*6.283,r=2+Math.random()*30,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r*.75;
      if(!free(x,y,R_SM)||!landOk(x,y,4))continue;
      if(mataNear(x,y,m=>(m.cat==='plant'&&Math.abs(m.x-x)<7&&Math.abs(m.y-y)<3)||(m.cat==='tree'&&Math.abs(m.x-x)<m.cr+3&&Math.abs(m.y-y)<4)||(m.cat==='rock'&&Math.abs(m.x-x)<m.s.w*.4&&Math.abs(m.y-y)<m.s.h*.3)))continue;
      mataAdd(mkM('plant',wpick('plant'),x,y,Math.random()<.5?1:0));n++}}
  /* mais borboletas na mata */
  for(let i=0;i<22;i++)flies.push(mkFly());
  initBugs();
}
function pushMata(objs,camX,camY){
  if(!MIM.complete)return;
  const c0=Math.floor((camX-70)/64),c1=Math.floor((camX+W+70)/64),r0=Math.floor((camY-6)/64),r1=Math.floor((camY+H+135)/64);
  for(let a=c0;a<=c1;a++)for(let b=r0;b<=r1;b++){const L=MG.get(a*1000+b);if(!L)continue;
    for(const m of L){if(m.x<camX-m.s.w/2-4||m.x>camX+W+m.s.w/2+4||m.y<camY-4||m.y>camY+H+m.s.h+4)continue;objs.push(m)}}
  pushBugs(objs,camX,camY);
}
function drawMata(m,sx,sy,t){
  const s=m.s,x0=sx-(s.w>>1),y0=sy-s.h+2;
  if(m.cat==='tree'){swayDraw(MIM,s.x,s.y,s.w,s.h,x0,y0,m.x,m.y,m.amp,0);return}
  if(m.cat==='rock'){g.drawImage(MIM,s.x,s.y,s.w,s.h,x0,y0,s.w,s.h);return}
  if(!GFXP||s.h<12){g.drawImage(MIM,s.x,s.y,s.w,s.h,x0,y0,s.w,s.h);return}
  /* balanço leve do arbusto/planta (faixas de 3 px) + empurrão quando o jogador passa */
  const near=Math.abs(p.x-m.x)<s.w*.5+4&&Math.abs(p.y-m.y)<7,sk=near?Math.sin(t*34)*1.1:0,gust=Math.sin(t*.7+m.x*.01)*.5;
  for(let y=0;y<s.h;y+=3){const hh=Math.min(3,s.h-y),u=1-y/s.h,off=Math.round(u*u*m.amp*(Math.sin(t*1.6+m.sw+y*.1)+gust)+u*sk);
    g.drawImage(MIM,s.x,s.y+y,s.w,hh,x0+off,y0+y,s.w,hh)}
}

/* ================= INSETOS ================= */
const BUGS=[],MOTHS=[],VAGA=[];
const flipS=c=>mkc(c.width,c.height,q=>{q.translate(c.width,0);q.scale(-1,1);q.drawImage(c,0,0)});
const W2=(c,x,y,w,h)=>R_(c,x,y,w,h,'rgba(232,244,255,.82)');
const BEES=[0,1].map(f=>mkc(8,6,c=>{
  if(f){W2(c,1,2,3,1);W2(c,4,2,2,1)}else{W2(c,1,0,2,2);W2(c,3,0,2,1)}
  R_(c,2,3,5,2,'#f4c62a');R_(c,3,3,1,2,'#2a1a0a');R_(c,5,3,1,2,'#2a1a0a');R_(c,0,3,2,2,'#3a2410');R_(c,7,4,1,1,'#2a1a0a')}));
const BEESF=BEES.map(flipS);
const DRG=['#2f86d8','#d8402f','#3ec8b0','#8a5ae0'].map(col=>[0,1].map(f=>mkc(13,7,c=>{
  if(f){W2(c,3,2,4,1);W2(c,7,2,4,1);W2(c,3,4,4,1);W2(c,7,4,4,1)}else{W2(c,3,0,4,2);W2(c,7,0,4,2);W2(c,2,1,1,1)}
  R_(c,2,3,8,1,col);R_(c,10,2,2,2,'#1f3d5a');R_(c,11,2,1,1,'#fff6c0');R_(c,0,3,2,1,col);R_(c,4,3,1,1,'#fff6c0')})));
const DRGF=DRG.map(a=>a.map(flipS));
const LADY=mkc(5,4,c=>{R_(c,0,1,5,3,'#d8302a');R_(c,1,0,3,1,'#1a1410');R_(c,2,1,1,3,'#1a1410');R_(c,1,2,1,1,'#1a1410');R_(c,3,3,1,1,'#1a1410');R_(c,0,3,1,1,'#8a1d18')});
const CRK=[0,1].map(f=>mkc(8,5,c=>{
  R_(c,2,1,4,2,'#4a3320');R_(c,3,1,2,1,'#6e4f30');R_(c,6,1,2,2,'#33220f');R_(c,7,2,1,1,'#e8d890');
  if(f){R_(c,0,2,2,1,'#33220f');R_(c,1,3,3,1,'#33220f');R_(c,3,3,1,2,'#33220f');R_(c,6,0,2,1,'#33220f')}else{R_(c,1,3,1,2,'#33220f');R_(c,3,3,1,2,'#33220f');R_(c,6,3,1,1,'#33220f');R_(c,5,0,2,1,'#33220f')}}));
const CRKF=CRK.map(flipS);
const ANT=[0,1].map(f=>mkc(4,3,c=>{R_(c,0,1,3,1,'#1a1410');R_(c,3,1,1,1,'#3a2418');R_(c,f?0:1,2,1,1,'#1a1410');R_(c,f?2:3,2,1,1,'#1a1410');R_(c,f?1:0,0,1,1,'#1a1410')}));
const ANTL=mkc(3,3,c=>{R_(c,0,1,3,2,'#5cbb55');R_(c,1,0,1,1,'#8bd870')});
const MOTH=[0,1,2].map(f=>mkc(11,7,c=>{
  const w=[3,2,1][f],col='#e8dcb8',sh='#b4a47c';
  for(const sd of[-1,1])for(let y=0;y<6;y++){const ww=w+(y<3?y:5-y)*(f===2?0:1);for(let x=1;x<=Math.min(5,ww+1);x++)R_(c,5+sd*x,y,1,1,x===ww+1||y===0?sh:col)}
  R_(c,5,1,1,5,'#5a4a30');R_(c,4,0,1,1,'#5a4a30');R_(c,6,0,1,1,'#5a4a30')}));

function pickMataAt(x,y,cats){
  const cx=(x/64)|0,cy=(y/64)|0;
  for(let k=0;k<10;k++){const L=MG.get((cx+((Math.random()*3)|0)-1)*1000+(cy+((Math.random()*3)|0)-1));if(!L||!L.length)continue;const m=L[(Math.random()*L.length)|0];if(cats.includes(m.cat))return m}
  return null}
const ANTTR=[];let ANTID=0;
function antApply(b,tr){b.ax=tr.ax;b.ay=tr.ay;b.bx=tr.bx;b.by=tr.by;b.trid=tr.id;b.x=tr.ax;b.y=tr.ay;b.z=0;b.u=b.u0}
function bugSpawn(b){
  const T=b.t;
  if(T==='formiga'){const tr=ANTTR[b.tr];if(tr&&Math.hypot(tr.ax-p.x,tr.ay-p.y)<420){antApply(b,tr);return true}}
  for(let k=0;k<(T==='libelula'?40:16);k++){
    const a=Math.random()*6.283,r=(T==='libelula'?20:46)+Math.random()*(T==='libelula'?330:270),x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;
    if(x<RIM+14||y<RIM+14||x>WS-RIM-14||y>WS-RIM-14)continue;
    const tt=terr(x,y);
    if(T==='libelula'){if(tt!==WATER&&tt!==MUD)continue;b.x=x;b.y=y;b.z=10+Math.random()*8;b.hx=x;b.hy=y;b.st='h';b.w=Math.random()*1.5;b.dir=1;b.c=(Math.random()*4)|0;return true}
    if(T==='abelha'){const m=pickMataAt(x,y,['bush','plant']);if(!m||tt===WATER)continue;b.home=m;b.x=m.x+(Math.random()-.5)*20;b.y=m.y+(Math.random()-.5)*6;b.z=8+Math.random()*8;b.tx=b.x;b.ty=b.y;b.w=Math.random()*1.5;b.dir=1;return true}
    if(T==='joaninha'){const m=pickMataAt(x,y,['bush']);if(!m)continue;b.home=m;b.ox=(Math.random()-.5)*m.s.w*.5;b.oy=-(m.s.h*(.25+Math.random()*.4));b.x=m.x+b.ox;b.y=m.y+1;b.z=-b.oy;b.w=Math.random()*3;b.dir=1;b.tox=b.ox;b.toy=b.oy;return true}
    if(T==='grilo'){if(tt!==GRASS&&tt!==DIRT)continue;b.x=x;b.y=y;b.z=0;b.w=Math.random()*3;b.dir=Math.random()<.5?1:-1;b.hop=0;return true}
    if(T==='formiga'){if(tt!==GRASS&&tt!==DIRT)continue;
      const ang=Math.random()*6.283,len=26+Math.random()*30,bx=x+Math.cos(ang)*len,by=y+Math.sin(ang)*len*.6;
      if(!landOk(bx,by,4)||!landOk(x,y,4))continue;
      ANTTR[b.tr]={ax:x,ay:y,bx,by,id:++ANTID};antApply(b,ANTTR[b.tr]);return true}
  }
  return false}
function initBugs(){
  BUGS.length=0;MOTHS.length=0;VAGA.length=0;
  const mk=(t,n)=>{for(let i=0;i<n;i++)BUGS.push({k:91,t,x:0,y:0,z:0,on:false,rs:Math.random()*2,ph:Math.random()*20,tm:Math.random()*9,wait:Math.random()*2,sd:i})};
  mk('abelha',18);mk('libelula',9);mk('joaninha',14);mk('grilo',14);
  for(let tr=0;tr<5;tr++)for(let i=0;i<7;i++)BUGS.push({k:91,t:'formiga',on:false,rs:0,x:0,y:0,z:0,ph:i,tm:0,u0:i/7,tr,sd:i,lead:i===0});
  for(let i=0;i<12;i++)MOTHS.push({x:0,y:0,z:8+Math.random()*14,a:Math.random()*6.28,ph:Math.random()*20,tm:Math.random()*9,on:false,rs:Math.random()*2});
  for(let i=0;i<80;i++)VAGA.push({x:0,y:0,z:4+Math.random()*20,a:Math.random()*6.28,ph:Math.random()*40,tm:Math.random()*9,on:false,rs:Math.random()*2,sp:3+Math.random()*5,bl:1.3+Math.random()*1.6,hu:Math.random()<.35?1:0})
}
const bugDay=()=>{const d=dkv(),rain=typeof WX!=='undefined'&&WX.rain>.25;return d<.5&&!rain};
function updBugs(dt){
  if(!BUGS.length)return;
  const day=bugDay(),rainy=typeof WX!=='undefined'&&WX.rain>.25;
  const antTrail={};
  for(const b of BUGS){
    const T=b.t,act=(T==='grilo'?!rainy:T==='formiga'?!rainy:day);
    b.act=act;
    const far=Math.hypot(b.x-p.x,b.y-p.y)>440;
    if(!b.on||far){b.rs-=dt;if(b.rs<=0){b.rs=1.2+Math.random()*1.5;b.on=bugSpawn(b);}if(!b.on)continue}
    if(!act)continue;
    b.tm+=dt;
    if(T==='abelha'){
      b.wait-=dt;
      if(b.wait>0){b.x+=Math.sin(b.tm*13+b.ph)*.12;b.z+=((b.hz||8)-b.z)*Math.min(1,dt*3)}
      else{const dx=b.tx-b.x,dy=b.ty-b.y,d=Math.hypot(dx,dy);
        if(d<2){b.wait=.8+Math.random()*2.4;const h=b.home;
          if(Math.random()<.3){const m=pickMataAt(b.x+(Math.random()-.5)*160,b.y+(Math.random()-.5)*100,['bush','plant']);if(m)b.home=m}
          const H=b.home;b.tx=H.x+(Math.random()-.5)*H.s.w*.8;b.ty=H.y+(Math.random()-.5)*6;b.hz=Math.max(5,H.s.h*(.35+Math.random()*.5))}
        else{const sp=30+Math.sin(b.tm*3+b.ph)*8;b.x+=dx/d*sp*dt;b.y+=dy/d*sp*dt+Math.sin(b.tm*9+b.ph)*.1;b.dir=dx>=0?1:-1;b.z+=((b.hz||10)+Math.sin(b.tm*7+b.ph)*2-b.z)*Math.min(1,dt*3)}}
    }
    else if(T==='libelula'){
      b.wait-=dt;
      if(b.st==='h'){b.x+=Math.sin(b.tm*17+b.ph)*.1;b.y+=Math.cos(b.tm*13+b.ph)*.05;if(b.wait<=0){b.st='d';const a=Math.random()*6.283,r=40+Math.random()*70;let tx=b.x+Math.cos(a)*r,ty=b.y+Math.sin(a)*r*.6;
          if(terr(tx,ty)!==WATER&&terr(tx,ty)!==MUD){tx=b.hx+(Math.random()-.5)*90;ty=b.hy+(Math.random()-.5)*50}b.tx=tx;b.ty=ty;b.tz=8+Math.random()*12}}
      else{const dx=b.tx-b.x,dy=b.ty-b.y,d=Math.hypot(dx,dy);if(d<3){b.st='h';b.wait=.5+Math.random()*2.2;if(Math.random()<.4){b.hx=b.x;b.hy=b.y}}
        else{const sp=78;b.x+=dx/d*sp*dt;b.y+=dy/d*sp*dt;b.dir=dx>=0?1:-1;b.z+=(b.tz-b.z)*Math.min(1,dt*4)}}
    }
    else if(T==='joaninha'){
      b.wait-=dt;const H=b.home;
      if(b.wait<=0){b.tox=(Math.random()-.5)*H.s.w*.55;b.toy=-(H.s.h*(.2+Math.random()*.5));b.wait=1.5+Math.random()*4}
      const dx=b.tox-b.ox,dy=b.toy-b.oy,d=Math.hypot(dx,dy);if(d>.6){b.ox+=dx/d*5*dt;b.oy+=dy/d*5*dt;b.dir=dx>=0?1:-1;b.mv=1}else b.mv=0;
      b.x=H.x+b.ox;b.y=H.y+1;b.z=-b.oy;
    }
    else if(T==='grilo'){
      if(b.hop>0){b.hop-=dt;const u=1-b.hop/.32;b.x+=b.vx*dt;b.y+=b.vy*dt;b.z=Math.sin(u*Math.PI)*6;if(b.hop<=0){b.z=0;b.wait=1+Math.random()*4}}
      else{b.wait-=dt;const dp=Math.hypot(b.x-p.x,b.y-p.y);
        if(b.wait<=0||dp<24){const a=dp<24?Math.atan2(b.y-p.y,b.x-p.x)+(Math.random()-.5):Math.random()*6.283,s=dp<24?55:30;
          const nx=b.x+Math.cos(a)*s*.32,ny=b.y+Math.sin(a)*s*.32*.7,tt=terr(nx,ny);
          if(tt===GRASS||tt===DIRT){b.vx=Math.cos(a)*s;b.vy=Math.sin(a)*s*.7;b.hop=.32;b.dir=b.vx>=0?1:-1}else b.wait=.4}}
    }
    else if(T==='formiga'){
      {const tr=ANTTR[b.tr];if(tr&&b.trid!==tr.id)antApply(b,tr)}
      const sp=.16;b.u=(b.u+dt*sp)%2;   // 0..1 vai carregando · 1..2 volta
      const u=b.u<1?b.u:2-b.u,j=Math.sin(b.tm*3+b.ph)*.6;
      b.x=b.ax+(b.bx-b.ax)*u+j*.4;b.y=b.ay+(b.by-b.ay)*u+j*.3;b.carry=b.u<1;b.dir=b.u<1?(b.bx>=b.ax?1:-1):(b.bx>=b.ax?-1:1);
    }
  }
  /* mariposas noturnas */
  const d=dkv();
  for(const m of MOTHS){
    if(d<.25){m.on=false;continue}
    if(!m.on||Math.hypot(m.x-p.x,m.y-p.y)>420){m.rs-=dt;if(m.rs<=0){m.rs=.8;const a=Math.random()*6.283,r=40+Math.random()*240,x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;if(terr(x,y)!==WATER){m.x=x;m.y=y;m.on=true}}if(!m.on)continue}
    m.tm+=dt;m.a+=(Math.sin(m.tm*2.4+m.ph)*3.2+Math.sin(m.tm*5.7+m.ph*2)*2)*dt;
    const dp=Math.hypot(p.x-m.x,p.y-m.y);if(dp>46)m.a+=angd(Math.atan2(p.y-m.y,p.x-m.x),m.a)*Math.min(1,dt*.6);   // atraídas pela luz do explorador
    const sp=16+Math.sin(m.tm*1.7+m.ph)*6;m.x+=Math.cos(m.a)*sp*dt;m.y+=Math.sin(m.a)*sp*dt*.7;m.z+=((14+Math.sin(m.tm*1.3+m.ph)*8)-m.z)*Math.min(1,dt*1.5);
  }
  /* vagalumes */
  const va=sst(.12,.55,d)*(typeof WX!=='undefined'?1-Math.min(.9,WX.rain*1.3):1);
  for(const v of VAGA){
    if(va<.02){v.on=false;continue}
    if(!v.on||Math.hypot(v.x-p.x,v.y-p.y)>380){v.rs-=dt;if(v.rs<=0){v.rs=.5+Math.random();
        for(let k=0;k<14;k++){const a=Math.random()*6.283,r=14+Math.random()*290,x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;
          if(x<RIM||y<RIM||x>WS-RIM||y>WS-RIM)continue;const tt=terr(x,y);if(tt===WATER)continue;
          if(FDN(x,y)<(k<10?.46:.3)&&tt!==MUD)continue;v.x=x;v.y=y;v.on=true;v.tm=Math.random()*9;break}}
      if(!v.on)continue}
    v.tm+=dt;v.a+=(Math.sin(v.tm*1.1+v.ph)*1.5+Math.sin(v.tm*2.9+v.ph*3)*1)*dt;
    const sp=v.sp*(.5+.5*Math.sin(v.tm*.8+v.ph));
    const nx=v.x+Math.cos(v.a)*sp*dt,ny=v.y+Math.sin(v.a)*sp*dt*.7;if(terr(nx,ny)===WATER&&Math.random()<.5)v.a+=Math.PI;else{v.x=nx;v.y=ny}
    v.z+=((8+Math.sin(v.tm*.7+v.ph)*8+v.ph%5)-v.z)*Math.min(1,dt*1.2);
    const pd=Math.hypot(v.x-p.x,v.y-p.y);if(pd<20){v.a=Math.atan2(v.y-p.y,v.x-p.x)+(Math.random()-.5)*.6;v.x+=Math.cos(v.a)*dt*14;v.y+=Math.sin(v.a)*dt*10}
  }
}
function pushBugs(objs,camX,camY){
  for(const b of BUGS){if(!b.on||!b.act)continue;if(b.x<camX-14||b.x>camX+W+14||b.y<camY-4||b.y>camY+H+40)continue;objs.push(b)}}
function drawBug(b,sx,sy,t){
  const T=b.t,fl=Math.floor((t+b.ph)*(T==='libelula'?34:T==='abelha'?30:12))&1,z=Math.round(b.z);
  let s,ox,oy;
  if(T==='abelha'){s=(b.dir<0?BEESF:BEES)[fl];ox=4;oy=3}
  else if(T==='libelula'){s=(b.dir<0?DRGF:DRG)[b.c][b.st==='h'?fl:(Math.floor(t*48)&1)];ox=6;oy=3}
  else if(T==='joaninha'){s=LADY;ox=2;oy=2}
  else if(T==='grilo'){s=(b.dir<0?CRKF:CRK)[b.hop>0?1:0];ox=4;oy=4}
  else{s=ANT[Math.floor(t*7+b.ph)&1];ox=2;oy=2}
  g.drawImage(s,sx-ox,sy-z-oy);
  if(T==='formiga'&&b.carry)g.drawImage(ANTL,sx-1,sy-4);
}
/* a luz da noite: vagalumes e mariposas brilham por cima do escuro */
function drawVaga(camX,camY,t){
  const d=dkv();if(d<.1||!VAGA.length)return;
  const va=sst(.12,.55,d)*(typeof WX!=='undefined'?1-Math.min(.9,WX.rain*1.3):1);
  g.save();g.globalCompositeOperation='lighter';
  for(const v of VAGA){if(!v.on)continue;const sx=Math.round(v.x-camX),sy=Math.round(v.y-camY-v.z+Math.sin(t*2+v.ph)*1.2);
    if(sx<-8||sx>W+8||sy<-8||sy>H+8)continue;
    const ph=(t*v.bl+v.ph)%3.2,b=ph<1.1?Math.sin(ph/1.1*Math.PI):0,k=Math.max(.05,b)*va;   // pisca: acende e some
    if(k<.06)continue;
    const c=v.hu?'196,255,110':'236,255,120';
    g.fillStyle='rgba('+c+','+(.07*k).toFixed(3)+')';g.fillRect(sx-3,sy-2,7,5);g.fillRect(sx-2,sy-3,5,7);
    g.fillStyle='rgba('+c+','+(.2*k).toFixed(3)+')';g.fillRect(sx-2,sy-1,5,3);g.fillRect(sx-1,sy-2,3,5);
    g.fillStyle='rgba(255,255,200,'+Math.min(1,k*1.2).toFixed(3)+')';g.fillRect(sx,sy,1,1);
    if(k>.5){g.fillStyle='rgba(255,255,220,'+(k*.9).toFixed(3)+')';g.fillRect(sx,sy,2,1)}
    g.fillStyle='rgba(0,0,0,0)';
  }
  g.restore();
  g.save();g.globalAlpha=Math.min(.8,(d-.25)*2.2);
  for(const m of MOTHS){if(!m.on)continue;const sx=Math.round(m.x-camX),gy=Math.round(m.y-camY),sy=Math.round(gy-m.z);
    if(sx<-8||sx>W+8||sy<-8||sy>H+8)continue;
    g.drawImage(MOTH[[0,1,2,1][Math.floor((t+m.ph)*18)&3]],sx-4,sy-3,9,6)}
  g.restore();
}

