  if(cats.some(c=>c.b===b)){say('Cuidado, tem uma lagarta aí!');return}
  const n=1+(Math.random()<.35?1:0);
  if(!canAdd('mato')){say('Mochila cheia!');return}
  addItem('mato',n);b.cut=150;cutB.push(b);p.swing=.28;
  const q=BUSM[b.i];
  for(let k=0;k<9;k++){const C=['#4f9a2a','#3d7a1e','#8fd24f','#5bbd32'];rchips.push({x:b.x+(Math.random()-.5)*q[2]*.7,y:b.y-q[3]*.3,z:3+Math.random()*6,vx:(Math.random()-.5)*34,vy:(Math.random()-.5)*14,vz:35+Math.random()*45,t:0,c:C[(Math.random()*4)|0]})}
